namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
San Marzano tomatoes
Fresh mozzarella
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F (245°C).
2. Roll out dough on a floured surface.
3. Spread crushed tomatoes evenly.
4. Tear mozzarella and distribute over sauce.
5. Bake for 10-12 minutes until crust is golden.
6. Top with fresh basil and a drizzle of olive oil.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Garam masala
Turmeric
Cumin
Coriander
Tomato sauce
Heavy cream
Garlic
Ginger
Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.
2. Grill or pan-fry chicken until charred.
3. Sauté onion, garlic, and ginger.
4. Add tomato sauce and spices, simmer 15 min.
5. Stir in cream and cooked chicken.
6. Simmer 10 more minutes. Serve with rice.", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in a skillet.
2. Add taco seasoning and water, simmer 5 min.
3. Warm tortillas in a dry pan.
4. Assemble tacos with beef and toppings.
5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles
Shrimp or tofu
Eggs
Bean sprouts
Green onions
Peanuts
Lime
Fish sauce
Tamarind paste
Sugar
Chili flakes", Steps = "1. Soak rice noodles in warm water 30 min.
2. Make sauce: mix tamarind, fish sauce, and sugar.
3. Stir-fry shrimp/tofu, push aside, scramble eggs.
4. Add drained noodles and sauce, toss together.
5. Add bean sprouts and green onions.
6. Serve with crushed peanuts and lime wedges.", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour
Vanilla extract
Powdered sugar", Steps = "1. Preheat oven to 425°F (220°C). Butter ramekins.
2. Melt chocolate and butter together.
3. Whisk eggs, sugar, and vanilla until thick.
4. Fold in chocolate mixture, then flour.
5. Pour into ramekins, bake 12-14 minutes.
6. Invert onto plates, dust with powdered sugar.", AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce
Parmesan cheese
Croutons
Caesar dressing
Lemon juice
Garlic
Anchovy paste
Olive oil", Steps = "1. Wash and chop romaine lettuce.
2. Make dressing: whisk garlic, anchovy paste, lemon, and olive oil.
3. Toss lettuce with dressing.
4. Top with shaved Parmesan and croutons.
5. Serve immediately.", AverageRating = 4.0, RatingCount = 6 },
            new() { Id = 7, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook spaghetti in salted water until al dente.
2. Crisp guanciale in a pan.
3. Whisk eggs with grated Pecorino and pepper.
4. Toss hot pasta with guanciale (off heat).
5. Quickly stir in egg mixture to create creamy sauce.
6. Serve with extra cheese and pepper.", AverageRating = 4.7, RatingCount = 19 },
            new() { Id = 8, Title = "Mango Lassi", Category = "Beverages", Ingredients = "Ripe mango
Yogurt
Milk
Sugar
Cardamom powder
Ice cubes", Steps = "1. Peel and chop ripe mango.
2. Blend mango, yogurt, milk, and sugar until smooth.
3. Add a pinch of cardamom.
4. Serve over ice cubes.", AverageRating = 4.3, RatingCount = 10 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
        {
            _ratings[recipeId] = new List<int>();
            // Seed with existing average
            for (int i = 0; i < recipe.RatingCount; i++)
                _ratings[recipeId].Add((int)Math.Round(recipe.AverageRating));
        }

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

